    """Set or clear the `.smoke` marker batch._is_real_checkpoint reads.

    Clearing matters as much as setting. `save_pretrained` does not empty the
    directory, so a marker left by an earlier --smoke run used to survive a real
    one forever: _is_real_checkpoint then never skipped train, while train's own
    clobber guard refused to overwrite without --overwrite, and the run became
    unrunnable through the batch runner.
    """
    marker = os.path.join(checkpoint_dir, ".smoke")
    if smoke:
        open(marker, "w").close()
    elif os.path.exists(marker):
        os.remove(marker)

