sys.path.insert(0, ".")
from training.config_schema import validate_config
for p in ["configs/e31-browsergym-e2-cosine-menu-qwen3-1_7b.yaml",
          "configs/e32-browsergym-e3-nontermination-menu-qwen3-1_7b.yaml"]:
    cfg = yaml.safe_load(open(p))
    validate_config(cfg)
    print("VALID", p)

# single-knob proof: diff each arm vs e30, ignoring id/description
def strip(c):
    c = dict(c); c.pop("experiment_id"); c.pop("description"); return c
e30 = strip(yaml.safe_load(open("configs/e30-browsergym-e1-menu-qwen3-1_7b.yaml")))
for p in ["configs/e31-browsergym-e2-cosine-menu-qwen3-1_7b.yaml",
          "configs/e32-browsergym-e3-nontermination-menu-qwen3-1_7b.yaml"]:
    arm = strip(yaml.safe_load(open(p)))
    diffs = []
    for k in set(e30) | set(arm):
        if e30.get(k) != arm.get(k):
            if k == "rewards":
                for rk in set(e30[k]) | set(arm[k]):
                    if e30[k].get(rk) != arm[k].get(rk):
                        diffs.append(f"rewards.{rk}: {e30[k].get(rk)} -> {arm[k].get(rk)}")
            else:
                diffs.append(f"{k}: DIFFERS")
    print(p.split("/")[-1], "diff vs e30:", diffs)
EOF

